		if snap.KVUtilization > 0.65 {
			kvP := (snap.KVUtilization - 0.65) / 0.35
			scores[snap.ID] *= (1.0 - 0.65*kvP*kvP)
		}

		// Large input: prefer instances with more free memory
		if inputLen > 200 && snap.FreeKVBlocks > 0 {
			memBonus := float64(snap.FreeKVBlocks) / float64(snap.FreeKVBlocks+150)
			scores[snap.ID] *= (1.0 + 0.14*memBonus)
		}

		// Floor to avoid zeroing
		if scores[snap.ID] < 0.001 {
			scores[snap.ID] = 0.001
		}
	}

	// Argmax selection
	bestScore := -1.0
	bestIdx := 0
	for i, snap := range snapshots {
		if scores[snap.ID] > bestScore {
			bestScore = scores[snap.ID]
			bestIdx = i
		}
	}
